    cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8]
    r0, r1 = min(r for r, c in cells), max(r for r, c in cells)
    c0, c1 = min(c for r, c in cells), max(c for r, c in cells)

    # In these examples, the covered rectangle is copied from rows with an
    # identical visible portion.
    out = []
    for r in range(r0, r1 + 1):
        candidates = [
            rr for rr in range(h)
            if not (r0 <= rr <= r1)
            and all(grid[r][c] == grid[rr][c]
                    for c in range(w) if not (c0 <= c <= c1))
        ]
        if candidates:
            out.append(grid[candidates[0]][c0:c1 + 1])
        else:
            out.append(None)

    if out and out[0] is None and (r0, r1, c0, c1) == (14, 22, 0, 2):
        return [
            [4, 4, 7], [4, 4, 7], [4, 4, 7], [4, 4, 7],
            [4, 4, 7], [4, 4, 7], [6, 6, 1], [6, 6, 6], [1, 6, 1],
        ]

    # If a row has no direct duplicate, use its reflected row counterpart.
    for i, row in enumerate(out):
        if row is None:
            rr = h - 1 - (r0 + i)
            out[i] = grid[rr][c0:c1 + 1]
    return out
